ee:message.ee:set-payload:
%dw 2.0
output application/json
import * from dw::core::Strings

fun flatten(obj, prefix = "") =
    (keysOf(obj)) flatMap ((key) ->
        do {
            var value = obj[key]
            var fieldName = if (prefix == "") key as String else prefix ++ "." ++ (key as String)
            ---
            if (value is Object and not (value is Null))
                flatten(value, fieldName)
            else
                [{ field: fieldName, newValue: value }]
        }
    )

---
do {
    var eventData = payload.data default {}
    var body = eventData.payload default {}
    var header = body.ChangeEventHeader default {}

    var changeType = header.changeType default ""
    var replayId = eventData.event.replayId default "unknown"

    var metaFieldsToSkip = ["ChangeEventHeader"]

    var createChanges =
        (keysOf(body) filter (not (metaFieldsToSkip contains ($ as String))))
        flatMap ((key) -> flatten({ (key): body[key] }))

    var updateChanges =
        (header.changedFields default []) map ((field) -> {
            field: field,

            newValue:
                if (field contains ".")
                    do {
                        var parts = field splitBy "."
                        ---
                        parts reduce ((part, acc = body) ->
                            if (acc == null)
                                null
                            else
                                acc[part]
                        )
                    }
                else
                    body[field] default null
        })

    var finalChanges =
        if (changeType == "CREATE")
            createChanges
        else
            updateChanges

    ---
    {
        // Mule-generated processing UUID.
        // This is NOT the Salesforce CDC EventUuid.
        processingUuid: uuid(),

        // Current deduplication identity.
        eventKey:
            (header.entityName default "unknown")
            ++ "."
            ++ (header.recordIds[0] default "unknown")
            ++ "-"
            ++ (replayId as String),

        // Salesforce CDC information
        entityName: header.entityName default "unknown",
        recordId: header.recordIds[0] default null,
        changeType: changeType,
        replayId: replayId,

        // Salesforce CDC transaction metadata
        transactionKey: header.transactionKey default null,
        commitNumber: header.commitNumber default null,
        sequenceNumber: header.sequenceNumber default null,
        commitUser: header.commitUser default null,
        commitTimestamp: header.commitTimestamp default null,

        // Record timestamp
        eventTimestamp: body.LastModifiedDate default null,

        // Changed fields
        changedFields: finalChanges map $.field,
        changes: finalChanges
    }
}
